/**
 * P-45.1.1
 * Nomenclature of Organic Chemistry: IUPAC Recommendations and Preferred Names 2013 (the Blue Book)
 *
 * “Multiplicative nomenclature is senior to substitutive nomenclature for generating preferred IUPAC
 * names to express multiple occurrences of identical senior parent structures, other than alkanes, in
 * the name of the parent structure (see P-51.3.1). In most cases multiplicative names are shorter than
 * regular substitutive names. A preferred IUPAC name is generated by multiplicative nomenclature when
 * the following criteria for its use are met (see P-51.3.1).
 * (1) the linking bonds (single or multiple) between the central substituent group of the
 * multiplicative group and all subsequent structural units are identical; and
 * (2) the multiplicative groups, other than the central multiplicative group, are symmetrically
 * substituted; and
 * (3) the locants of all substituent groups on the identical parent structures, including suffix
 * groups, are identical.
 * When these conditions are not met, substitutive nomenclature generates preferred IUPAC names.”
 *
 * Examples with a drawing are drawn, not written out, in the Blue Book. The checks read
 * their names, but can only check the structure against the drawing once the drawings are used.
 */
import { checkRule } from '../support/checkRule.js';

checkRule('P-45.1.1', [
  // Drawn in the Blue Book.
  { drawing: 'P4gif/P450101a.gif', pin: '4,4′-oxybis(2-chlorobenzoic acid)' },
  // Drawn in the Blue Book.
  { drawing: 'P4gif/P450101a.gif', pin: '4-(4-carboxy-2-chlorophenoxy)-2-chlorobenzoic acid' },
]);
